vec2 uv_y = uv+vec2(dx,dy)*(vec2(1.0)/uTexSize) * 4.0;
ret = mix(ret,vec3(0.8,0.6, 0.0),GetBlur1(uv_y).x);
ret = mix(ret, 1.0 ,GetPixel(uv).z*(1.0 - GetBlur1(uv).x));
ret = mix(ret,vec3( 0.0 , 0.0 , 0.0),GetBlur1(uv).z*1.2);
ret = mix(ret, 2.0 ,GetPixel(uv).x);
float rad_lq = rad * length(uTexSize.xy)*0.5;
