vec2 uv_temp1 = (uv - 0.5) * uTexSize.xy;
float rad_hq = length(uv_temp1);
float ang_hq = atan(-uv_temp1.y, uv_temp1.x);
vec2 uv2 = (uv - 0.5);
float rad2 = rad_lq*0.8;
float ang2 = ang_lq * M_INV_PI_2 + rad_lq*0.000 + uTime*0.00;
// FIN TYPE
float fins = 6;
ang2 = fract(ang2*fins)/fins;
// ENABLE THIS TO MAKE THE FINS ALTERNATE: (q7 = 1 or 0)
ang2 = abs(ang2 - 0.5/fins);
ang2 *= M_PI_2;
uv = 0.5 + rad2*vec2(cos(ang2),sin(ang2))*(vec2(1.0)/uTexSize);
ret = 1.4*pow(1.25*clamp01(GetBlur1(uv))*rad_lq,0.333)*vec3(0.8,1.4,2.3); //invert
ret = vec3( 1.0 ) - ret;
}

